@app.route('/api/settings/restart', methods=['POST'])
@login_required
@permission_required('tab.settings')
def api_restart_server():
    import os
    import threading
    import time
    def _do_exit():
        time.sleep(0.6)  # дать время вернуть JSON-ответ
        print('=' * 60)
        print('[SERVER] Принудительный перезапуск по запросу администратора')
        print('=' * 60)
        os._exit(0)
    threading.Thread(target=_do_exit, daemon=True).start()
    _audit(db, current_user(db), 'update', 'server', 'restart', {})
    return jsonify({'success': True, 'message': 'Сервер завершает работу'})

/* ============================================================
   PATCH 1.0.9 — Перезапуск сервера
   ============================================================ */
(function(){
'use strict';
if (window.__trkRestartBtn) return;
window.__trkRestartBtn = true;

function _csrf(){ return window.REESTR_CSRF || ''; }
function _notify(msg, kind){
    if (typeof window.__settingsNotify === 'function') {
        try { window.__settingsNotify(msg, kind); return; } catch(e){}
    }
    if (typeof window.__trackerNotify === 'function') {
        try { window.__trackerNotify(msg, kind); return; } catch(e){}
    }
}

function _restart(){
    if (!confirm('Вы уверены, что хотите перезапустить сервер?\n\nСайт станет недоступен на несколько секунд.\nЕсли вы не настроили автоперезапуск (START.bat), вам придётся запустить его вручную.')) return;

    var btn = document.getElementById('restartServerBtn');
    if (btn) {
        btn.disabled = true;
        btn.textContent = '⏳ Перезапуск...';
    }

    _notify('🔄 Отправка команды на перезапуск...');
    var h = {'Content-Type': 'application/json'};
    if (_csrf()) h['X-CSRF-Token'] = _csrf();

    fetch('/api/settings/restart', {
        method: 'POST', credentials: 'same-origin', headers: h
    }).then(function(r){
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
    }).then(function(d){
        if (d && d.success) {
            _notify('✅ Сервер останавливается...', 'success');
            // Пытаемся переподключиться через 3 секунды
            var attempts = 0;
            var iv = setInterval(function(){
                attempts++;
                fetch('/login', {method: 'HEAD', cache: 'no-store'})
                    .then(function(){ location.reload(); })
                    .catch(function(){
                        if (attempts > 20) {
                            clearInterval(iv);
                            document.body.innerHTML = '<div style="text-align:center;padding:40px;font-family:sans-serif;color:#333;"><h2>Сервер остановлен</h2><p>Пожалуйста, запустите <b>START.bat</b> заново.</p></div>';
                        }
                    });
            }, 1000);
        } else {
            _notify('❌ ' + ((d && d.error) || 'Ошибка'), 'error');
            if (btn) { btn.disabled = false; btn.textContent = '🔄 Перезапустить сервер'; }
        }
    }).catch(function(e){
        _notify('❌ ' + (e.message || 'Ошибка'), 'error');
        if (btn) { btn.disabled = false; btn.textContent = '🔄 Перезапустить сервер'; }
    });
}

document.addEventListener('click', function(e){
    if (e.target && e.target.closest && e.target.closest('#restartServerBtn')) {
        e.preventDefault();
        _restart();
    }
});

// Если кнопка уже есть (пользователь на вкладке), но нет обработчика — сработает делегирование выше.
})();
